test("no deduction is offered on a board that cannot be completed", () => {
  const solution = fromString(REFERENCE.solution);
  const origin = fromString(REFERENCE.puzzle);
  let checked = 0;

  for (let cell = 0; cell < 81 && checked < 12; cell += 1) {
    if (origin[cell] !== EMPTY) continue;
    const bad = wrongButLegal(origin, solution, cell);
    if (bad === null) continue;
    const board = origin.slice();
    board[cell] = bad;
    const hint = nextHint(board, solution, {
      origin,
      edits: [{ cell, from: EMPTY, to: bad }],
    });
    assert.equal(
      hint.kind,
      "dead-end",
      `offered ${hint.kind} on a dead board at cell ${cell}`,
    );
    checked += 1;
  }
  assert.ok(checked > 0, "no scenario exercised");
});

