test("hint is idempotent: asking twice without acting gives the same answer", () => {
  for (const p of PUZZLES.slice(0, 10)) {
    const board = fromString(p.puzzle);
    const solution = fromString(p.solution);
    const a = nextHint(board, solution);
    const b = nextHint(board, solution);
    assert.deepEqual(a, b, "hint changed without the board changing");
  }
});

test("the last empty cell is deduced, never revealed", () => {
  const solution = fromString(REFERENCE.solution);
  const board = solution.slice();
  board[40] = EMPTY;
  const hint = nextHint(board, solution);
  assert.equal(hint.kind, "deduction");
  assert.ok(hint.kind === "deduction" && hint.deduction.cell === 40);
  assert.ok(hint.kind === "deduction" && hint.deduction.digit === solution[40]);
});

test("a complete but wrong board is a conflict, not a dead end", () => {
  // A full board that breaks no constraint *is* a solution, so any complete
  // wrong board must contain a duplicate somewhere.
  const board = fromString(REFERENCE.solution);
  board[0] = board[1]!;
  const hint = nextHint(board);
  assert.equal(hint.kind, "conflict");
});

test("two independent wrong entries rewind past both", () => {
  const origin = fromString(REFERENCE.puzzle);
  const solution = fromString(REFERENCE.solution);
  const board = origin.slice();
  const edits: Edit[] = [];

  const wrongCells: number[] = [];
  for (let cell = 0; cell < 81 && wrongCells.length < 2; cell += 1) {
    if (board[cell] !== EMPTY) continue;
    const bad = wrongButLegal(board, solution, cell);
    if (bad === null) continue;
    edits.push({ cell, from: EMPTY, to: bad });
    board[cell] = bad;
    wrongCells.push(cell);
  }
  assert.equal(wrongCells.length, 2, "precondition");

  const dead = findDeadEnd(origin, edits)!;
  assert.equal(dead.editIndex, 0, "must rewind past the earlier mistake too");

  const rewound = origin.slice();
  for (let i = 0; i < dead.editIndex; i += 1) rewound[edits[i]!.cell] = edits[i]!.to;
  assert.ok(solve(rewound).solution !== null);
});

test("a wrong entry followed by correct ones still blames the wrong one", () => {
  const origin = fromString(REFERENCE.puzzle);
  const solution = fromString(REFERENCE.solution);
  const board = origin.slice();
  const edits: Edit[] = [];

  const badCell = board.findIndex((v) => v === EMPTY);
  const bad = wrongButLegal(board, solution, badCell)!;
  edits.push({ cell: badCell, from: EMPTY, to: bad });
  board[badCell] = bad;

  let placed = 0;
  for (let cell = 0; cell < 81 && placed < 4; cell += 1) {
    if (board[cell] !== EMPTY) continue;
    edits.push({ cell, from: EMPTY, to: solution[cell]! });
    board[cell] = solution[cell]!;
    placed += 1;
  }

  const dead = findDeadEnd(origin, edits)!;
  assert.equal(dead.cell, badCell);
  assert.equal(dead.editIndex, 0, "the correct entries after it must go too");
});

test("correcting a wrong entry in place clears the dead end", () => {
  const origin = fromString(REFERENCE.puzzle);
  const solution = fromString(REFERENCE.solution);
  const cell = origin.findIndex((v) => v === EMPTY);
  const bad = wrongButLegal(origin, solution, cell)!;
  const edits: Edit[] = [
    { cell, from: EMPTY, to: bad },
    { cell, from: bad, to: solution[cell]! },
  ];
  assert.equal(findDeadEnd(origin, edits), null);
});

test("an empty edit list on a good board reports nothing", () => {
  const origin = fromString(REFERENCE.puzzle);
  assert.equal(findDeadEnd(origin, []), null);
});

