import { fromString } from "./board";
import { N_CELLS } from "./units";

export interface StoredGame {
  version: 1;
  puzzleId: string | null;
  origin: string;
  board: string;
  notes: number[][];
}

/** Parse browser storage defensively; stale or corrupt state never breaks startup. */
export function parseStoredGame(raw: string | null): StoredGame | null {
  if (raw === null) return null;
  try {
    const value = JSON.parse(raw) as Partial<StoredGame>;
    if (value.version !== 1) return null;
    if (value.puzzleId !== null && typeof value.puzzleId !== "string") return null;
    if (typeof value.origin !== "string" || typeof value.board !== "string") return null;
    fromString(value.origin);
    fromString(value.board);
    if (!Array.isArray(value.notes) || value.notes.length !== N_CELLS) return null;
    const notes = value.notes.map((cell) => {
      if (!Array.isArray(cell)) throw new Error("invalid notes");
      const digits = cell.filter(
        (digit): digit is number => Number.isInteger(digit) && digit >= 1 && digit <= 9,
      );
      return [...new Set(digits)].sort((a, b) => a - b);
    });
    return {
      version: 1,
      puzzleId: value.puzzleId,
      origin: value.origin,
      board: value.board,
      notes,
    };
  } catch {
    return null;
  }
}

export function serializeStoredGame(game: StoredGame): string {
  return JSON.stringify(game);
}

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { fromString, type Board } from "./board";
import { solve, type SolveEvent } from "./solve";

interface LibraryPuzzle {
  id: string;
  puzzle: string;
}

const puzzles = JSON.parse(
  readFileSync(new URL("../../public/puzzles.json", import.meta.url), "utf8"),
) as LibraryPuzzle[];

function replay(start: Board, events: SolveEvent[]): Board {
  const board = start.slice();
  for (const event of events) {
    switch (event.kind) {
      case "given":
      case "contradiction":
      case "solved":
        break;
      case "naked-single":
      case "hidden-single":
      case "branch":
        board[event.cell] = event.digit;
        break;
      case "backtrack":
        for (const cell of event.cells) board[cell] = 0;
        break;
    }
  }
  return board;
}

test("every recorded solver trace replays to the exact solution", () => {
  for (const puzzle of puzzles) {
    const start = fromString(puzzle.puzzle);
    const { solution, stats } = solve(start, true);
    assert.notEqual(solution, null, `${puzzle.id} should solve`);
    assert.equal(stats.events.at(-1)?.kind, "solved", `${puzzle.id} should finish its trace`);
    assert.deepEqual(replay(start, stats.events), solution, `${puzzle.id} trace diverged`);
  }
});

/**
 * Propagation and search, ported from `src/gridmind/propagate.py` and
 * `src/gridmind/solvers/backtracking.py`.
 *
 * The one addition over the Python version is the **event log**. Every
 * inference and every branch can be recorded, which is what makes Lessons 46
 * and 47 possible: you replay the log to animate the solver's reasoning
 * instead of just showing the answer.
 */

import { EMPTY, type Board } from "./board";
import { N, N_CELLS, PEERS, UNITS } from "./units";

export const FULL_MASK = (1 << N) - 1;

export type Domains = Int16Array;

export const bit = (digit: number): number => 1 << (digit - 1);
export const popcount = (mask: number): number => {
  let count = 0;
  let m = mask;
  while (m) {
    m &= m - 1;
    count += 1;
  }
  return count;
};
export const onlyDigit = (mask: number): number => 32 - Math.clz32(mask);
export const maskToDigits = (mask: number): number[] => {
  const digits: number[] = [];
  for (let d = 1; d <= N; d += 1) if (mask & bit(d)) digits.push(d);
  return digits;
};

export type SolveEvent =
  | { kind: "given"; cell: number; digit: number }
  | { kind: "naked-single"; cell: number; digit: number }
  | { kind: "hidden-single"; cell: number; digit: number; unit: number }
  | { kind: "branch"; cell: number; digit: number; candidates: number[] }
  | { kind: "backtrack"; cell: number; digit: number; cells: number[] }
  | { kind: "contradiction"; cell: number }
  | { kind: "solved" };

export interface SearchStats {
  /** When false, counters still update but no events are captured. */
  record: boolean;
  nodes: number;
  backtracks: number;
  propagations: number;
  /** Solutions found. Only `countSolutions` looks for more than one. */
  solutions: number;
  events: SolveEvent[];
  ms: number;
}

const pushEvent = (stats: SearchStats | undefined, event: SolveEvent): void => {
  if (stats?.record) stats.events.push(event);
};

export const emptyStats = (record = false): SearchStats => ({
  record,
  nodes: 0,
  backtracks: 0,
  propagations: 0,
  solutions: 0,
  events: [],
  ms: 0,
});

export function initialDomains(
  board: Board,
  stats?: SearchStats,
): Domains | null {
  const domains = new Int16Array(N_CELLS).fill(FULL_MASK);
  for (let cell = 0; cell < N_CELLS; cell += 1) {
    const value = board[cell]!;
    if (value === EMPTY) continue;
    if (!(domains[cell]! & bit(value))) return null;
    domains[cell] = bit(value);
    pushEvent(stats, { kind: "given", cell, digit: value });
    for (const peer of PEERS[cell]!) {
      domains[peer]! &= ~bit(value);
      if (domains[peer] === 0) {
        pushEvent(stats, { kind: "contradiction", cell: peer });
        return null;
      }
    }
  }
  return domains;
}

export function nakedSingles(
  domains: Domains,
  stats?: SearchStats,
  traceBoard?: Board,
): boolean {
  const queue: number[] = [];
  for (let cell = 0; cell < N_CELLS; cell += 1) {
    if (popcount(domains[cell]!) === 1) queue.push(cell);
  }
  // Process cells in row-major discovery order. A stack produced the same
  // solution, but made the visible trace start at the bottom-right and jump
  // around as new singles appeared. FIFO gives the teaching replay a stable,
  // natural reading order without changing any inference rule.
  let head = 0;
  while (head < queue.length) {
    const cell = queue[head++]!;
    const mask = domains[cell]!;
    if (popcount(mask) !== 1) continue;
    if (traceBoard !== undefined && traceBoard[cell] === EMPTY) {
      const digit = onlyDigit(mask);
      traceBoard[cell] = digit;
      pushEvent(stats, { kind: "naked-single", cell, digit });
    }
    for (const peer of PEERS[cell]!) {
      if (domains[peer]! & mask) {
        domains[peer]! &= ~mask;
        if (domains[peer] === 0) {
          pushEvent(stats, { kind: "contradiction", cell: peer });
          return false;
        }
        if (popcount(domains[peer]!) === 1) {
          queue.push(peer);
        }
      }
    }
  }
  return true;
}

export function hiddenSingles(
  domains: Domains,
  stats?: SearchStats,
  traceBoard?: Board,
): boolean {
  let changed = true;
  while (changed) {
    changed = false;
    for (let u = 0; u < UNITS.length; u += 1) {
      const unit = UNITS[u]!;
      for (let digit = 1; digit <= N; digit += 1) {
        const mask = bit(digit);
        const homes = unit.filter((cell) => domains[cell]! & mask);
        if (homes.length === 0) return false;
        if (homes.length === 1) {
          const cell = homes[0]!;
          if (domains[cell] !== mask) {
            domains[cell] = mask;
            changed = true;
            if (traceBoard === undefined || traceBoard[cell] === EMPTY) {
              if (traceBoard !== undefined) traceBoard[cell] = digit;
              pushEvent(stats, {
                kind: "hidden-single",
                cell,
                digit,
                unit: u,
              });
            }
            if (!nakedSingles(domains, stats, traceBoard)) return false;
          }
        }
      }
    }
  }
  return true;
}

export function propagate(
  domains: Domains,
  stats?: SearchStats,
  traceBoard?: Board,
): boolean {
  if (stats) stats.propagations += 1;
  if (!nakedSingles(domains, stats, traceBoard)) return false;
  return hiddenSingles(domains, stats, traceBoard);
}

/** MRV: branch on the cell with the fewest candidates. -1 when all decided. */
export function mrv(domains: Domains): number {
  let bestCell = -1;
  let bestSize = N + 1;
  for (let cell = 0; cell < N_CELLS; cell += 1) {
    const size = popcount(domains[cell]!);
    if (size > 1 && size < bestSize) {
      bestSize = size;
      bestCell = cell;
      if (size === 2) break;
    }
  }
  return bestCell;
}

function search(
  domains: Domains,
  stats: SearchStats,
  out: { result: Domains | null },
  traceBoard?: Board,
): boolean {
  const cell = mrv(domains);
  if (cell < 0) {
    out.result = domains.slice();
    pushEvent(stats, { kind: "solved" });
    return true;
  }

  stats.nodes += 1;
  const candidates = maskToDigits(domains[cell]!);
  for (const digit of candidates) {
    pushEvent(stats, { kind: "branch", cell, digit, candidates });
    const branch = domains.slice();
    branch[cell] = bit(digit);
    const branchTrace = traceBoard?.slice();
    if (branchTrace !== undefined) branchTrace[cell] = digit;
    if (propagate(branch, stats, branchTrace)) {
      if (search(branch, stats, out, branchTrace)) return true;
    }
    stats.backtracks += 1;
    const cells: number[] = [];
    if (branchTrace === undefined || traceBoard === undefined) {
      cells.push(cell);
    } else {
      // A failed guess must undo every deduction made beneath it, not only
      // the guessed cell. This makes the event stream independently replayable.
      for (let index = 0; index < N_CELLS; index += 1) {
        if (traceBoard[index] === EMPTY && branchTrace[index] !== EMPTY) cells.push(index);
      }
    }
    pushEvent(stats, { kind: "backtrack", cell, digit, cells });
  }
  return false;
}

export interface SolveResult {
  solution: Board | null;
  stats: SearchStats;
}

export function solve(board: Board, record = false): SolveResult {
  const stats = emptyStats(record);
  const started = performance.now();

  const domains = initialDomains(board, stats);
  if (domains === null) {
    stats.ms = performance.now() - started;
    return { solution: null, stats };
  }
  // The trace board is deliberately separate from domains: it records exactly
  // what a viewer has seen so every new singleton is emitted once.
  const traceBoard = record ? board.slice() : undefined;
  if (!propagate(domains, stats, traceBoard)) {
    stats.ms = performance.now() - started;
    return { solution: null, stats };
  }

  const out: { result: Domains | null } = { result: null };
  search(domains, stats, out, traceBoard);
  stats.ms = performance.now() - started;

  if (out.result === null) return { solution: null, stats };
  const solution = new Uint8Array(N_CELLS);
  for (let cell = 0; cell < N_CELLS; cell += 1) {
    solution[cell] = onlyDigit(out.result[cell]!);
  }
  return { solution, stats };
}

/**
 * Count solutions, stopping at `limit`.
 *
 * Distinguishing "exactly one solution" from "many" is what tells a hint
 * whether anything is actually forced. Checking for a *second* solution is far
 * cheaper than enumerating them all.
 */
export function countSolutions(board: Board, limit = 2): number {
  const stats = emptyStats();
  const domains = initialDomains(board);
  if (domains === null) return 0;
  if (!propagate(domains, stats)) return 0;
  const out: { result: Domains | null } = { result: null };
  searchCounting(domains, stats, out, limit);
  return stats.solutions;
}

function searchCounting(
  domains: Domains,
  stats: SearchStats,
  out: { result: Domains | null },
  limit: number,
): boolean {
  const cell = mrv(domains);
  if (cell < 0) {
    stats.solutions += 1;
    out.result = domains.slice();
    return stats.solutions >= limit;
  }
  stats.nodes += 1;
  for (const digit of maskToDigits(domains[cell]!)) {
    const branch = domains.slice();
    branch[cell] = bit(digit);
    if (propagate(branch, stats)) {
      if (searchCounting(branch, stats, out, limit)) return true;
    }
  }
  return false;
}

/** Candidate sets after propagation only — what Lesson 47 renders. */
export function candidatesAfterPropagation(board: Board): Domains | null {
  const domains = initialDomains(board);
  if (domains === null) return null;
  return propagate(domains) ? domains : null;
}

/**
 * Grid structure: units, peers, and the constraint graph.
 *
 * This is the TypeScript twin of `src/gridmind/units.py`. Keeping the two in
 * step is deliberate — Lesson 45 asks you to port the solver and check that
 * both implementations agree node-for-node on the same puzzles.
 */

export const N = 9;
export const BOX = 3;
export const N_CELLS = N * N;

export const rcToIndex = (row: number, col: number): number => row * N + col;
export const indexToRc = (index: number): [number, number] => [
  Math.floor(index / N),
  index % N,
];

export const boxOf = (index: number): number => {
  const [row, col] = indexToRc(index);
  return Math.floor(row / BOX) * BOX + Math.floor(col / BOX);
};

const buildRows = (): number[][] =>
  Array.from({ length: N }, (_, r) =>
    Array.from({ length: N }, (_, c) => rcToIndex(r, c)),
  );

const buildCols = (): number[][] =>
  Array.from({ length: N }, (_, c) =>
    Array.from({ length: N }, (_, r) => rcToIndex(r, c)),
  );

const buildBoxes = (): number[][] => {
  const boxes: number[][] = Array.from({ length: N }, () => []);
  for (let cell = 0; cell < N_CELLS; cell += 1) boxes[boxOf(cell)]!.push(cell);
  return boxes;
};

export const ROWS = buildRows();
export const COLS = buildCols();
export const BOXES = buildBoxes();

/** All 27 units: nine rows, nine columns, nine boxes. */
export const UNITS: number[][] = [...ROWS, ...COLS, ...BOXES];

/** The three units each cell belongs to. */
export const UNITS_OF: number[][][] = Array.from({ length: N_CELLS }, (_, cell) =>
  UNITS.filter((unit) => unit.includes(cell)),
);

/** The 20 cells that constrain each cell. */
export const PEERS: number[][] = Array.from({ length: N_CELLS }, (_, cell) => {
  const peers = new Set<number>();
  for (const unit of UNITS_OF[cell]!) {
    for (const other of unit) if (other !== cell) peers.add(other);
  }
  return [...peers].sort((a, b) => a - b);
});

/** Undirected constraint graph, each edge once with a < b. 810 of them. */
export const EDGES: Array<[number, number]> = (() => {
  const edges: Array<[number, number]> = [];
  for (let a = 0; a < N_CELLS; a += 1) {
    for (const b of PEERS[a]!) if (a < b) edges.push([a, b]);
  }
  return edges;
})();

/** Grid rendering, selection and editing. Lessons 43 and 44 live here. */

import { EMPTY, findConflicts, type Board } from "../core/board";
import { N_CELLS, PEERS } from "../core/units";
import { maskToDigits, type Domains } from "../core/solve";

export interface GridView {
  /** Redraw from the current board. */
  render(): void;
  /** Replace the board and redraw. Clears the selection. */
  setBoard(board: Board): void;
  getBoard(): Board;
  /** Cells that were given, so rendering can distinguish them from deductions. */
  setGivens(givens: boolean[]): void;
  isGiven(cell: number): boolean;
  /** Optional candidate overlay, or null to hide it. */
  setCandidates(domains: Domains | null): void;
  /** Highlight a single cell, e.g. during animation. */
  setActive(cell: number | null): void;
  /** Mark cells filled by search rather than inference. */
  setBranchCells(cells: Set<number>): void;
  /** Cells a hint is currently talking about. */
  setHighlight(cells: number[]): void;

  /** The cell the user is editing, or null. */
  getSelected(): number | null;
  setSelected(cell: number | null): void;

  /** Write a digit into the selected cell. False if that is not allowed. */
  enterDigit(digit: number): boolean;
  /** Clear the selected cell. False if it is empty or a given. */
  eraseSelected(): boolean;
  /** Toggle a pencil mark in the selected empty cell. */
  toggleNote(digit: number): boolean;
  /** Serializable pencil marks for session recovery. */
  getNotes(): number[][];
  setNotes(notes: number[][]): void;
  /** Digits already taken by the cell's 20 peers — used to grey out pad keys. */
  digitsUsedByPeers(cell: number): Set<number>;

  /** Step back/forward through the user's own entries. */
  undo(): boolean;
  redo(): boolean;
  canUndo(): boolean;
  canRedo(): boolean;
  /** Drop the history, e.g. when a new puzzle is loaded. */
  clearHistory(): void;
  /** The user's applied edits, oldest first — used to trace a dead end. */
  getEntries(): Array<{ cell: number; from: number; to: number }>;
  /** Undo back to just before edit `index`. Returns how many steps it took. */
  undoTo(index: number): number;
  /** Number of undoable actions back to value edit `index`. */
  actionsToEntry(index: number): number;

  onChange(handler: () => void): void;
  onSelect(handler: (cell: number | null) => void): void;
}

export function createGrid(container: HTMLElement): GridView {
  let board: Board = new Uint8Array(N_CELLS);
  let givens: boolean[] = new Array(N_CELLS).fill(false);
  let candidates: Domains | null = null;
  let notes: Array<Set<number>> = Array.from({ length: N_CELLS }, () => new Set());
  // Null, not 0: an app that opens with a cell already highlighted looks like
  // it has state the user did not create.
  let selected: number | null = null;
  let active: number | null = null;
  let branchCells = new Set<number>();
  let highlighted = new Set<number>();
  let changeHandler: () => void = () => {};
  let selectHandler: (cell: number | null) => void = () => {};

  /** One entry per user edit. Solver output is not recorded — undoing a solve
      would be meaningless, since Reset reloads the puzzle anyway. */
  interface CellState {
    value: number;
    notes: number[];
  }

  interface Edit {
    cell: number;
    before: CellState;
    after: CellState;
  }
  let history: Edit[] = [];
  let historyAt = 0;

  function stateAt(cell: number): CellState {
    return { value: board[cell]!, notes: [...notes[cell]!].sort((a, b) => a - b) };
  }

  function applyState(cell: number, state: CellState): void {
    board[cell] = state.value;
    notes[cell] = new Set(state.notes);
  }

  function record(cell: number, before: CellState, after: CellState): void {
    // A new edit after undoing discards the redo tail, as in any editor.
    history = history.slice(0, historyAt);
    history.push({ cell, before, after });
    historyAt = history.length;
  }

  const cells: HTMLDivElement[] = [];
  container.replaceChildren();
  container.setAttribute("aria-rowcount", "9");
  container.setAttribute("aria-colcount", "9");
  for (let index = 0; index < N_CELLS; index += 1) {
    const cell = document.createElement("div");
    cell.className = "cell";
    cell.setAttribute("role", "gridcell");
    cell.tabIndex = index === 0 ? 0 : -1;
    // pointerdown rather than click: it fires before focus moves, so the
    // selection is already correct when the pad reads it, and it avoids the
    // ~300ms tap delay some mobile browsers still apply to click.
    cell.addEventListener("pointerdown", (event) => {
      event.preventDefault();
      select(index);
      cell.focus({ preventScroll: true });
    });
    container.append(cell);
    cells.push(cell);
  }

  function select(cell: number | null): void {
    // Re-selecting the same cell is a no-op rather than a toggle: on touch it
    // is far too easy to tap twice and lose your place.
    if (cell === selected) return;
    selected = cell;
    render();
    selectHandler(selected);
  }

  function isGiven(cell: number): boolean {
    return givens[cell] === true;
  }

  function enterDigit(digit: number): boolean {
    if (selected === null || digit < 1 || digit > 9) return false;
    if (isGiven(selected)) return false;
    // Tapping the digit already in the cell clears it — the standard
    // toggle in sudoku apps, and it saves reaching for erase.
    if (board[selected] === digit) return eraseSelected();
    const before = stateAt(selected);
    board[selected] = digit;
    notes[selected]!.clear();
    record(selected, before, stateAt(selected));
    candidates = null;
    changeHandler();
    render();
    return true;
  }

  function eraseSelected(): boolean {
    if (selected === null) return false;
    if (isGiven(selected)) return false;
    if (board[selected] === EMPTY && notes[selected]!.size === 0) return false;
    const before = stateAt(selected);
    board[selected] = EMPTY;
    notes[selected]!.clear();
    record(selected, before, stateAt(selected));
    candidates = null;
    changeHandler();
    render();
    return true;
  }

  function toggleNote(digit: number): boolean {
    if (selected === null || digit < 1 || digit > 9) return false;
    if (isGiven(selected) || board[selected] !== EMPTY) return false;
    const before = stateAt(selected);
    const cellNotes = notes[selected]!;
    if (cellNotes.has(digit)) cellNotes.delete(digit);
    else cellNotes.add(digit);
    record(selected, before, stateAt(selected));
    candidates = null;
    changeHandler();
    render();
    return true;
  }

  function digitsUsedByPeers(cell: number): Set<number> {
    // Reuses the existing peer relation rather than inventing a second notion
    // of "conflict" — same source of truth the solver uses.
    const used = new Set<number>();
    for (const peer of PEERS[cell]!) {
      const value = board[peer]!;
      if (value !== EMPTY) used.add(value);
    }
    return used;
  }

  function undo(): boolean {
    if (historyAt === 0) return false;
    historyAt -= 1;
    const edit = history[historyAt]!;
    applyState(edit.cell, edit.before);
    candidates = null;
    selected = edit.cell;
    changeHandler();
    render();
    selectHandler(selected);
    return true;
  }

  function redo(): boolean {
    if (historyAt >= history.length) return false;
    const edit = history[historyAt]!;
    historyAt += 1;
    applyState(edit.cell, edit.after);
    candidates = null;
    selected = edit.cell;
    changeHandler();
    render();
    selectHandler(selected);
    return true;
  }

  container.addEventListener("keydown", (event: KeyboardEvent) => {
    const key = event.key;

    if ((event.metaKey || event.ctrlKey) && key.toLowerCase() === "z") {
      if (event.shiftKey) redo();
      else undo();
      event.preventDefault();
      return;
    }

    if (key >= "1" && key <= "9") {
      if (selected === null) return;
      enterDigit(Number(key));
    } else if (key === "Backspace" || key === "Delete" || key === "0") {
      if (selected === null) return;
      eraseSelected();
    } else if (key === "Escape") {
      select(null);
    } else if (key.startsWith("Arrow")) {
      const current = selected ?? 0;
      const row = Math.floor(current / 9);
      const column = current % 9;
      const next =
        key === "ArrowLeft" && column > 0 ? current - 1
          : key === "ArrowRight" && column < 8 ? current + 1
            : key === "ArrowUp" && row > 0 ? current - 9
              : key === "ArrowDown" && row < 8 ? current + 9
                : current;
      if (next !== current || selected === null) {
        select(next);
        cells[next]!.focus({ preventScroll: true });
      }
    } else {
      return;
    }
    event.preventDefault();
  });

  function render(): void {
    const conflicts = new Set(findConflicts(board).flat());
    const peers = selected === null ? null : PEERS[selected]!;
    const selectedValue = selected === null ? EMPTY : board[selected]!;

    for (let index = 0; index < N_CELLS; index += 1) {
      const element = cells[index]!;
      const value = board[index]!;
      const row = Math.floor(index / 9) + 1;
      const column = (index % 9) + 1;
      element.className = "cell";
      element.replaceChildren();
      element.tabIndex = index === (selected ?? 0) ? 0 : -1;
      element.setAttribute("aria-rowindex", String(row));
      element.setAttribute("aria-colindex", String(column));
      element.setAttribute("aria-selected", String(index === selected));
      element.setAttribute("aria-readonly", String(givens[index] === true));

      if (value !== EMPTY) {
        element.textContent = String(value);
        if (givens[index]) element.classList.add("given");
        else if (branchCells.has(index)) element.classList.add("branch");
        else element.classList.add("derived");
      } else if (notes[index]!.size > 0 || candidates !== null) {
        const shown = notes[index]!.size > 0
          ? notes[index]!
          : new Set(maskToDigits(candidates![index]!));
        if (shown.size > 0) {
          const box = document.createElement("div");
          box.className = notes[index]!.size > 0 ? "candidates notes" : "candidates";
          for (let digit = 1; digit <= 9; digit += 1) {
            const slot = document.createElement("span");
            slot.textContent = shown.has(digit) ? String(digit) : "";
            box.append(slot);
          }
          element.append(box);
        }
      }

      if (index === selected) element.classList.add("selected");
      else if (peers !== null && peers.includes(index)) element.classList.add("peer");

      // Seeing every 7 at once is how people actually scan a sudoku.
      if (selectedValue !== EMPTY && value === selectedValue) {
        element.classList.add("same-digit");
      }
      if (highlighted.has(index)) element.classList.add("hinted");
      if (index === active) element.classList.add("active");
      if (conflicts.has(index)) element.classList.add("conflict");
      element.setAttribute("aria-invalid", String(conflicts.has(index)));

      const state = value === EMPTY
        ? notes[index]!.size > 0
          ? `empty, notes ${[...notes[index]!].sort((a, b) => a - b).join(", ")}`
          : "empty"
        : givens[index]
          ? `given ${value}`
          : `entered ${value}`;
      element.setAttribute(
        "aria-label",
        `Row ${row}, column ${column}, ${state}${conflicts.has(index) ? ", conflict" : ""}`,
      );
    }
  }

  render();

  return {
    render,
    setBoard(next) {
      board = next.slice();
      notes = Array.from({ length: N_CELLS }, () => new Set());
      selected = null;
      history = [];
      historyAt = 0;
      render();
      selectHandler(null);
    },
    getBoard: () => board.slice(),
    setGivens(next) {
      givens = next.slice();
      render();
    },
    isGiven,
    setCandidates(next) {
      candidates = next;
      render();
    },
    setActive(cell) {
      active = cell;
      render();
    },
    setBranchCells(next) {
      branchCells = next;
      render();
    },
    setHighlight(cells) {
      highlighted = new Set(cells);
      render();
    },
    getSelected: () => selected,
    setSelected: select,
    enterDigit,
    eraseSelected,
    toggleNote,
    getNotes: () => notes.map((values) => [...values].sort((a, b) => a - b)),
    setNotes(next) {
      notes = Array.from({ length: N_CELLS }, (_, index) => {
        const values = next[index] ?? [];
        return new Set(values.filter((digit) => digit >= 1 && digit <= 9));
      });
      render();
    },
    digitsUsedByPeers,
    undo,
    redo,
    getEntries: () => history
      .slice(0, historyAt)
      .filter((edit) => edit.before.value !== edit.after.value)
      .map((edit) => ({ cell: edit.cell, from: edit.before.value, to: edit.after.value })),
    undoTo(index) {
      const valueEdits = history
        .slice(0, historyAt)
        .map((edit, historyIndex) => ({ edit, historyIndex }))
        .filter(({ edit }) => edit.before.value !== edit.after.value);
      const target = valueEdits[index]?.historyIndex ?? 0;
      let steps = 0;
      while (historyAt > target && undo()) steps += 1;
      return steps;
    },
    actionsToEntry(index) {
      const valueEdits = history
        .slice(0, historyAt)
        .map((edit, historyIndex) => ({ edit, historyIndex }))
        .filter(({ edit }) => edit.before.value !== edit.after.value);
      const target = valueEdits[index]?.historyIndex ?? 0;
      return Math.max(0, historyAt - target);
    },
    canUndo: () => historyAt > 0,
    canRedo: () => historyAt < history.length,
    clearHistory() {
      history = [];
      historyAt = 0;
    },
    onChange(handler) {
      changeHandler = handler;
    },
    onSelect(handler) {
      selectHandler = handler;
    },
  };
}

/** Small, dependency-free experiments that run entirely in the browser. */

import { fromString } from "../core/board";
import { solve } from "../core/solve";

type Lab = (container: HTMLElement) => void;

function heading(container: HTMLElement, title: string, intro: string): HTMLElement {
  const header = document.createElement("div");
  header.className = "lab-header";
  const name = document.createElement("h2");
  name.textContent = title;
  const copy = document.createElement("p");
  copy.textContent = intro;
  header.append(name, copy);
  container.append(header);
  return header;
}

function action(label: string, run: () => void): HTMLButtonElement {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "primary";
  button.textContent = label;
  button.addEventListener("click", run);
  return button;
}

const EASY = "000260701680070090190004500820100040004602900050003028009300074040050036703018000";
const HARD = "000000000302540000050301070000000004409006005023054790000000050700810000080060009";

const searchLab: Lab = (container) => {
  heading(
    container,
    "Measure inference and search",
    "Run the real TypeScript solver. Node count is the number of guesses; zero means rules alone were enough.",
  );
  const controls = document.createElement("div");
  controls.className = "lab-controls";
  const select = document.createElement("select");
  select.setAttribute("aria-label", "Puzzle to measure");
  const puzzles: Array<[string, string]> = [
    [EASY, "Propagation-only puzzle"],
    [HARD, "Puzzle requiring search"],
  ];
  for (const [value, label] of puzzles) {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = label;
    select.append(option);
  }
  const output = document.createElement("output");
  output.className = "lab-output";
  const run = () => {
    const result = solve(fromString(select.value));
    output.textContent = result.solution === null
      ? "No solution"
      : `${result.stats.nodes} search nodes · ${result.stats.backtracks} backtracks · ` +
        `${result.stats.propagations} propagated values`;
  };
  controls.append(select, action("Run solver", run));
  container.append(controls, output);
  run();
};

const encodingLab: Lab = (container) => {
  heading(
    container,
    "One cell, three representations",
    "Choose a cell value. Notice which encodings imply an ordering and which preserve category or set structure.",
  );
  const keys = document.createElement("div");
  keys.className = "lab-digit-keys";
  const output = document.createElement("div");
  output.className = "encoding-output";

  const render = (digit: number) => {
    for (const button of keys.querySelectorAll("button")) {
      button.classList.toggle("active", button.textContent === String(digit));
    }
    output.replaceChildren();
    const rows: Array<[string, string, string]> = [
      ["Dense integer", String(digit), "Compact, but the number looks ordered to a model."],
      ["One-hot", Array.from({ length: 10 }, (_, i) => i === digit ? "1" : "0").join(" "), "Categories without a false distance."],
      ["Candidate bit", digit === 0 ? "000000000" : (1 << (digit - 1)).toString(2).padStart(9, "0"), "A set representation suited to constraint propagation."],
    ];
    for (const [label, value, description] of rows) {
      const row = document.createElement("div");
      const title = document.createElement("strong");
      title.textContent = label;
      const code = document.createElement("code");
      code.textContent = value;
      const note = document.createElement("span");
      note.textContent = description;
      row.append(title, code, note);
      output.append(row);
    }
  };

  for (let digit = 0; digit <= 9; digit += 1) {
    const key = document.createElement("button");
    key.type = "button";
    key.textContent = String(digit);
    key.setAttribute("aria-label", digit === 0 ? "Empty cell" : `Digit ${digit}`);
    key.addEventListener("click", () => render(digit));
    keys.append(key);
  }
  container.append(keys, output);
  render(7);
};

const leakageLab: Lab = (container) => {
  heading(
    container,
    "See data leakage",
    "Each letter is one base puzzle; numbered chips are augmented copies. A test set is honest only when base puzzles do not cross the split.",
  );
  const controls = document.createElement("div");
  controls.className = "lab-controls segmented";
  const visual = document.createElement("div");
  visual.className = "split-visual";

  const render = (grouped: boolean) => {
    controls.querySelectorAll("button").forEach((button, index) => {
      button.classList.toggle("active", grouped ? index === 1 : index === 0);
    });
    visual.replaceChildren();
    const splits = grouped
      ? [["Train", ["A1", "A2", "B1", "B2"]], ["Validation", ["C1", "C2", "D1", "D2"]]] as const
      : [["Train", ["A1", "B1", "C1", "D1"]], ["Validation", ["A2", "B2", "C2", "D2"]]] as const;
    for (const [name, values] of splits) {
      const group = document.createElement("section");
      const label = document.createElement("strong");
      label.textContent = name;
      const chips = document.createElement("div");
      for (const value of values) {
        const chip = document.createElement("span");
        chip.className = `split-chip group-${value[0]!.toLowerCase()}`;
        chip.textContent = value;
        chips.append(chip);
      }
      group.append(label, chips);
      visual.append(group);
    }
    const verdict = document.createElement("p");
    verdict.className = grouped ? "lab-verdict good" : "lab-verdict bad";
    verdict.textContent = grouped
      ? "Honest: validation contains entirely unseen base puzzles."
      : "Leaking: every validation puzzle has a near-duplicate in training.";
    visual.append(verdict);
  };

  const naive = document.createElement("button");
  naive.type = "button";
  naive.textContent = "Split rows";
  naive.addEventListener("click", () => render(false));
  const grouped = document.createElement("button");
  grouped.type = "button";
  grouped.textContent = "Split groups";
  grouped.addEventListener("click", () => render(true));
  controls.append(naive, grouped);
  container.append(controls, visual);
  render(false);
};

const accuracyLab: Lab = (container) => {
  heading(
    container,
    "Cell accuracy is not puzzle accuracy",
    "Even a strong per-cell model must get every empty cell right for the whole grid to count as solved.",
  );
  const form = document.createElement("div");
  form.className = "slider-lab";
  const accuracy = document.createElement("input");
  accuracy.type = "range";
  accuracy.min = "50";
  accuracy.max = "100";
  accuracy.step = "0.1";
  accuracy.value = "95";
  const empty = document.createElement("input");
  empty.type = "range";
  empty.min = "1";
  empty.max = "64";
  empty.value = "50";
  const accuracyLabel = document.createElement("label");
  const emptyLabel = document.createElement("label");
  const result = document.createElement("output");
  result.className = "probability-output";

  const render = () => {
    const p = Number(accuracy.value) / 100;
    const n = Number(empty.value);
    accuracyLabel.textContent = `Cell accuracy: ${Number(accuracy.value).toFixed(1)}%`;
    emptyLabel.textContent = `Empty cells: ${n}`;
    const grid = p ** n;
    result.textContent = `Expected whole-grid accuracy: ${(grid * 100).toLocaleString(undefined, { maximumFractionDigits: 4 })}%`;
  };
  accuracy.addEventListener("input", render);
  empty.addEventListener("input", render);
  form.append(accuracyLabel, accuracy, emptyLabel, empty, result);
  container.append(form);
  render();
};

const decodingLab: Lab = (container) => {
  heading(
    container,
    "Iterative decoding",
    "A model should fill its most confident empty cell, then run again with the new information instead of committing to every answer at once.",
  );
  const cells = document.createElement("div");
  cells.className = "decode-cells";
  const status = document.createElement("output");
  status.className = "lab-output";
  const rounds = [
    [[4, 0.98], [7, 0.61], [2, 0.54]],
    [[4, 1], [7, 0.88], [2, 0.65]],
    [[4, 1], [7, 1], [2, 0.96]],
    [[4, 1], [7, 1], [2, 1]],
  ] as const;
  let round = 0;
  const render = () => {
    cells.replaceChildren();
    rounds[round]!.forEach(([digit, confidence], index) => {
      const cell = document.createElement("div");
      cell.className = confidence === 1 ? "decode-cell filled" : "decode-cell";
      const value = document.createElement("strong");
      value.textContent = confidence === 1 ? String(digit) : "?";
      const score = document.createElement("span");
      score.textContent = confidence === 1 ? "committed" : `${digit} · ${Math.round(confidence * 100)}%`;
      cell.append(value, score);
      if (index === round && round < 3) cell.classList.add("next");
      cells.append(cell);
    });
    status.textContent = round === 3
      ? "Solved in three model passes. Each pass used the previous answer."
      : `Pass ${round + 1}: commit only the highest-confidence prediction, then run again.`;
  };
  const next = action("Commit next cell", () => {
    round = Math.min(3, round + 1);
    next.disabled = round === 3;
    render();
  });
  const reset = document.createElement("button");
  reset.type = "button";
  reset.textContent = "Reset";
  reset.addEventListener("click", () => {
    round = 0;
    next.disabled = false;
    render();
  });
  const controls = document.createElement("div");
  controls.className = "lab-controls";
  controls.append(next, reset);
  container.append(cells, controls, status);
  render();
};

const LABS: Record<number, Lab> = {
  5: searchLab,
  9: encodingLab,
  11: leakageLab,
  12: accuracyLab,
  17: decodingLab,
  19: accuracyLab,
  20: searchLab,
  24: searchLab,
};

export function hasLessonLab(lesson: number): boolean {
  return lesson in LABS;
}

export function mountLessonLab(lesson: number, container: HTMLElement): void {
  container.replaceChildren();
  container.className = "lesson-lab";
  LABS[lesson]?.(container);
}
